/// <summary>
/// MPJ_28153 Interbranch Transfers	DCP 01/08/2022
/// </summary>
[ExtensionOf(tableStr(WMSPickingRoute))]
final class METWMSPickingRouteTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Finishes multiple WMSPicking routes.
    /// </summary>
    /// <param name = "_packedList">A packed list of picking route ids, for routes that should be finished.</param>
    public static void finishMulti(container _packedList)
    {
        next finishMulti(_packedList); 

        WMSPickingRoute::METAdjustShipRemainMulti(_packedList);
        WMSPickingRoute::METUpdateInterncompanyPO(_packedList);
    }

    /// <summary>
    /// Added for the FSD-CB274 intercompany transfer.
    /// Fetch the Replenishment purchase order reference and update the quantity on it's lines.
    /// </summary>
    public static void METUpdateInterncompanyPO(container _metPackedList)
    {
        List                metPickingRouteIdList;
        boolean             updateDone = false;
        PurchLine           purchLine;
        SalesLine           salesLine;
        ListEnumerator      metListEnumerator;
        WMSPickingRouteId   metPickingRouteId;

        if (!_metPackedList)
        {
            return;
        }

        metPickingRouteIdList = List::create(_metPackedList);

        if (!metPickingRouteIdList)
        {
            return;
        }
        
        metListEnumerator = metPickingRouteIdList.getEnumerator();

        while (metListEnumerator.moveNext())
        {
            WMSPickingRoute pickingRouteTable;
            
            metPickingRouteId   = metListEnumerator.current();
            pickingRouteTable   = WMSPickingRoute::find(metPickingRouteId);

            while select ItemId, SalesQty, METReplenishmentPOReference from salesLine
                where salesLine.SalesId == pickingRouteTable.transRefId
                && salesLine.METReplenishmentPOReference != ''
            {
                PurchId purchId = salesLine.METReplenishmentPOReference;

                changecompany(VendParameters::find().METInterCompanyLegalEntity)
                {
                    select firstonly purchLine
                        where purchLine.PurchId == purchId
                        && purchLine.ItemId == salesLine.ItemId;

                    if (purchLine.RecId)
                    {
                        ttsbegin;
                        purchLine.selectForUpdate(true);
                        purchLine.PurchQty = salesLine.SalesQty;
                        purchLine.update();
                        ttscommit;

                        //Auto-confirm the purchase order.
                        METPurchaseOrderProcessHelper::confirmPurchaseOrder(purchLine.PurchId);
                    }
                }
            } 
        }
        
    }

    /// <summary>
    /// Reduce the Ship Remain qty to match what was pickied
    /// </summary>
    /// <param name = "_metPackedList">A packed list of picking route ids</param>
    public static void METAdjustShipRemainMulti(container _metPackedList)
    {
        List                metPickingRouteIdList;
        ListEnumerator      metListEnumerator;
        WMSPickingRouteId   metPickingRouteId;

        if (!_metPackedList)
        {
            return;
        }

        metPickingRouteIdList = List::create(_metPackedList);

        if (!metPickingRouteIdList)
        {
            return;
        }
        
        metListEnumerator = metPickingRouteIdList.getEnumerator();

        while (metListEnumerator.moveNext())
        {
            metPickingRouteId = metListEnumerator.current();

            InventTransferLine::METAdjustShipRemain(metPickingRouteId);
        }
    }

    /// <summary>
    /// CB626_TMSEngineSOPackingSlip
    /// Retrieve the WMS picking list number from the FO picking list number
    /// </summary>
    /// <param name = "_pickingRouteId">FO picking list number</param>
    /// <param name = "_isCSDWarehouse">Is CSD warehouse</param>
    /// <param name = "_internalCrossDock">Internal cross dock order</param>
    /// <returns>WMS picking list number</returns>
    public static METWMSPicklistNumber METGetWMSPicklistNumber(WMSPickingRouteID _pickingRouteId, METCSDWarehouse _isCSDWarehouse, METInternalCrossDockOrder _internalCrossDock)
    {
        METWMSPicklistNumber ret;

        // search for the SO Pick List with “Picking route” = PickListID, set:
        WMSPickingRoute wmsPickingRouteSO = WMSPickingRoute::find(_pickingRouteId);

        // If the SO is for a warehouse that is marked as “Is CSD warehouse” = Yes or the SO has “Internal Cross Dock” = Yes
        if (_isCSDWarehouse || _internalCrossDock)
        {
            // RelatedTOPickListID = the SO Pick list’s “Source TO Picking Route”
            WMSPickingRoute wmsPickingRouteTO = WMSPickingRoute::find(wmsPickingRouteSO.METTransferOrderPickingRouteId);

            // METPicklistReference as the link between FO picklist number and CCR/WMS pickList number
            ret = METPicklistReference::find(wmsPickingRouteTO.pickingRouteID).WMSPicklistNumber;
        }

        if (!ret)
        {
            ret = METPicklistReference::find(wmsPickingRouteSO.pickingRouteID).WMSPicklistNumber;
        }

        return ret;
    }
